      for (const key of /** @type {const} */ ([
        'interval_minutes', 'target_file_bytes', 'min_snapshots_to_keep',
        'max_snapshot_age_hours', 'compact_file_count', 'compact_avg_file_bytes',
        'compact_batch_bytes', 'max_tick_ms',
