}

/**
 * @param {unknown} v
 * @returns {v is string}
 */
function isNonEmptyString(v) {
  return typeof v === 'string' && v.length > 0
}

/** @param {unknown} err */
function describeError(err) {
  return err instanceof Error ? err.message : String(err)
